            card2Bg = "#f0f9ff";
            card2Text = "#0369a1";
            card3Border = "#6366f1";
            card3Bg = "#eef2ff";
            card3Text = "#4338ca";
            card4Border = "#d97706";
            card4Bg = "#fffbeb";
